:root {
  --bg-panel: #f0ebe0;
  --bg-header: #2b3a2e;
  --bg-body: #faf7f0;
  --bg-spec: #e8e0cc;
  --bg-entry-odd: #f5f0e4;
  --bg-entry-even: #ede6d4;
  --bg-footer: #2b3a2e;
  --color-accent: #c8872a;
  --color-accent-light: #e8a84a;
  --color-cream: #f7f2e4;
  --color-text-dark: #1a2019;
  --color-text-mid: #3d4f3a;
  --color-text-muted: #7a8f76;
  --color-text-light: #f0ebe0;
  --color-alt-high: #2e6b3e;
  --color-alt-mid: #c8872a;
  --color-alt-low: #9e3a28;
  --color-badge-exc: #2e6b3e;
  --color-stamp-border: #c8872a;
  --color-rule: #c8b89a;
}

article.glider-panel {
  width: 480px;
  background: var(--bg-panel);
  border: 2px solid var(--color-rule);
  border-radius: 6px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.panel-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  border-bottom: 3px solid var(--color-accent);
}

.club-badge {
  display: flex;
  align-items: center;
  gap: 10px;
}

.badge-icon {
  font-size: 26px;
  line-height: 1;
}

.badge-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.club-name {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: var(--color-accent-light);
  text-transform: uppercase;
}

.club-sub {
  font-size: 10px;
  color: var(--color-text-muted);
  letter-spacing: 0.05em;
}

.log-id {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 1px;
}

.log-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: var(--color-text-muted);
  text-transform: uppercase;
}

.log-num {
  font-size: 15px;
  font-weight: 700;
  color: var(--color-accent-light);
  letter-spacing: 0.05em;
}

.panel-body {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  background: var(--bg-body);
  flex: 1;
}

.glider-info {
  padding: 12px 14px;
  border-right: 1px solid var(--color-rule);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.glider-name {
  font-size: 12px;
  color: var(--color-text-mid);
  line-height: 1.3;
}

.glider-name strong {
  font-size: 15px;
  font-weight: 800;
  color: var(--color-text-dark);
  display: block;
}

.glider-reg {
  font-size: 11px;
  color: var(--color-text-muted);
}

.glider-reg strong {
  color: var(--color-text-dark);
  font-weight: 700;
}

.condition-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.cond-label {
  font-size: 10px;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.cond-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 3px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.cond-badge.excellent {
  background: var(--color-badge-exc);
  color: var(--color-cream);
}

.spec-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px 8px;
  margin-top: 4px;
  background: var(--bg-spec);
  border-radius: 4px;
  padding: 8px;
  border: 1px solid var(--color-rule);
}

.spec-item {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.spec-key {
  font-size: 9px;
  font-weight: 600;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.07em;
}

.spec-val {
  font-size: 12px;
  font-weight: 700;
  color: var(--color-text-dark);
}

.flight-log {
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.log-section-title {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-accent);
  border-bottom: 1px solid var(--color-rule);
  padding-bottom: 4px;
}

.flight-entries {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.flight-entry {
  display: grid;
  grid-template-columns: 38px 1fr auto auto;
  align-items: center;
  gap: 6px;
  padding: 4px 6px;
  border-radius: 3px;
  font-size: 11px;
}

.flight-entry:nth-child(odd) {
  background: var(--bg-entry-odd);
}

.flight-entry:nth-child(even) {
  background: var(--bg-entry-even);
}

.entry-date {
  font-size: 10px;
  font-weight: 600;
  color: var(--color-text-muted);
}

.entry-pilot {
  font-weight: 600;
  color: var(--color-text-dark);
}

.entry-duration {
  font-size: 10px;
  color: var(--color-text-mid);
}

.entry-alt {
  font-size: 10px;
  font-weight: 700;
  padding: 1px 5px;
  border-radius: 2px;
}

.entry-alt.high {
  color: var(--color-alt-high);
  background: #d4edd9;
}

.entry-alt.mid {
  color: var(--color-alt-mid);
  background: #f5e4c8;
}

.entry-alt.low {
  color: var(--color-alt-low);
  background: #f5d4cc;
}

.panel-footer {
  background: var(--bg-footer);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  border-top: 3px solid var(--color-accent);
}

.footer-left {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.next-label {
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-text-muted);
}

.next-date {
  font-size: 13px;
  font-weight: 700;
  color: var(--color-accent-light);
  letter-spacing: 0.04em;
}

.footer-stamps {
  display: flex;
  gap: 8px;
  align-items: center;
}

.stamp {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-align: center;
  line-height: 1.3;
  text-transform: uppercase;
  padding: 4px 8px;
  border: 2px solid var(--color-stamp-border);
  border-radius: 3px;
  color: var(--color-accent-light);
}
